sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    //空予定情報欄をクリックし、開始時間・終了時間を取得
    var start_time = api.state.newClientStateTime;
    var end_time = api.state.newClientEndTime;

    //時間変更
    function formatTimestamp(timestamp) {
        var date = new Date(timestamp);
        var year = date.getFullYear();
        var month = ("0" + (date.getMonth() + 1)).slice(-2);
        var day = ("0" + date.getDate()).slice(-2);
        var hours = ("0" + date.getHours()).slice(-2);
        var minutes = ("0" + date.getMinutes()).slice(-2);
        var seconds = ("0" + date.getSeconds()).slice(-2);
        var formattedDate = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
        return formattedDate;
    }
    //開始時間・終了時間を変換
    var start_date = formatTimestamp(start_time);
    var end_date = formatTimestamp(end_time);
    //変換した時間は変数に引き渡し
    api.setState("newClientStateTime", start_date);
    api.setState("newClientEndTime", end_date);

    //登録画面の初期開始・終了日付を設定
    api.setState("startDate", start_date.slice(0, 10));
    api.setState("endDate", end_date.slice(0, 10));

    //登録画面の初期開始・終了時刻だけ設定
    api.setState("startTime", start_date.slice(11, 16));
    api.setState("endTime", end_date.slice(11, 16));

}
